
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_k_pgsl025_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_k_pgsl025", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([2.001833618631128e+02, 1.415039266560782e+02, 1.103770173759155e+02, 9.146001579978260e+01, 7.727734974225724e+01, 6.434433673493699e+01, 5.147016395434645e+01, 3.909617249039830e+01, 2.888292607132684e+01, 2.224005282524123e+01, 1.485552673659021e+01, 3.608422831734816e+00, 1.937038830382570e+00, 1.374279399610823e+00, 9.624378404373013e-01, 9.335382044571503e-01, 1.772195414358160e+00, 1.085672666492257e+01, 2.088857560129759e+02, 1.390159001476526e+04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


